    init {
        Native.register(IntegrityCheckingUniffiLib::class.java, findLibraryName(componentName = "data_builder_for_operations_that_need_to_be_correct"))
        uniffiCheckContractApiVersion(this)
        uniffiCheckApiChecksums(this)
