/**
 * Error type Android sees. One string, no inner types. Rust code never
 * matches on this — it's constructed at the uniffi boundary.
 */
sealed class BuilderErr: kotlin.Exception() {
    
    class Failed(
        
        val v1: kotlin.String
        ) : BuilderErr() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BuilderErr> {
        override fun lift(error_buf: RustBuffer.ByValue): BuilderErr = FfiConverterTypeBuilderErr.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeBuilderErr : FfiConverterRustBuffer<BuilderErr> {
    override fun read(buf: ByteBuffer): BuilderErr {
        

        return when(buf.getInt()) {
            1 -> BuilderErr.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BuilderErr): ULong {
        return when(value) {
            is BuilderErr.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: BuilderErr, buf: ByteBuffer) {
        when(value) {
            is BuilderErr.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalTypeEverythingForEditBlock: FfiConverterRustBuffer<EverythingForEditBlock?> {
    override fun read(buf: ByteBuffer): EverythingForEditBlock? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterTypeEverythingForEditBlock.read(buf)
    }

    override fun allocationSize(value: EverythingForEditBlock?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterTypeEverythingForEditBlock.allocationSize(value)
        }
    }

    override fun write(value: EverythingForEditBlock?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterTypeEverythingForEditBlock.write(value, buf)
        }
    }
}




